import type { ReactNode } from 'react';
import { Text } from '../ui/text';
import type { Tweet as TweetType } from '../../types/bluebird';

export function formatTweetText(text: string, entities: Partial<TweetType['entities']>) {
  function getCodeUnitIndex(str: string, charIndex: number) {
    let codeUnitCount = 0;
    let currentCharCount = 0;
    for (let i = 0; i < str.length; i++) {
      if (currentCharCount === charIndex) {
        return codeUnitCount;
      }
      const charCode = str.charCodeAt(i);
      if (charCode >= 0xd800 && charCode <= 0xdbff) {
        i++;
      }
      codeUnitCount = i + 1;
      currentCharCount++;
    }
    return codeUnitCount;
  }

  function getCharIndex(str: string, codeUnitIndex: number): number {
    return [...str.substring(0, codeUnitIndex)].length;
  }

  let lastIndex = 0;
  const parts: ReactNode[] = [];

  const existingHashtags = entities.hashtags || [];
  const regex = /#\w+/g;
  let match;
  const regexHashtags: typeof existingHashtags = [];

  while ((match = regex.exec(text)) !== null) {
    const codeUnitStart = match.index;
    const codeUnitEnd = codeUnitStart + match[0].length;
    const charStart = getCharIndex(text, codeUnitStart);
    const charEnd = getCharIndex(text, codeUnitEnd);

    const alreadyExists = existingHashtags.some(
      (h) => h.indices[0] === charStart && h.indices[1] === charEnd
    );

    if (!alreadyExists) {
      regexHashtags.push({
        text: match[0].slice(1),
        indices: [charStart, charEnd]
      });
    }
  }

  const allHashtags = [...existingHashtags, ...regexHashtags];

  const sortedEntities = [
    ...allHashtags.map((h) => ({ ...h, type: 'hashtag' })),
    ...(entities.user_mentions || []).map((m) => ({ ...m, type: 'mention' }))
    //@ts-expect-error willfix
  ].sort((a, b) => a.indices[0] - b.indices[0]);

  sortedEntities.forEach((entity) => {
    //@ts-expect-error willfix
    const [charStart, charEnd] = entity.indices;
    const start = getCodeUnitIndex(text, charStart);
    const end = getCodeUnitIndex(text, charEnd);

    if (start > lastIndex) {
      parts.push(text.substring(lastIndex, start));
    }
    parts.push(
      <Text as="span" key={`${entity.type}-${start}`} color="colorPalette.default">
        {text.substring(start, end)}
      </Text>
    );
    lastIndex = end;
  });

  if (lastIndex < text.length) {
    parts.push(text.substring(lastIndex));
  }

  return parts;
}
